A.aOU=new B.B("Ula\u015f\u0131m kaynakl\u0131 sal\u0131m","Transport emissions")
A.aOV=new B.B(0,0)
A.aOW=new B.B(0,!0)
A.aOX=new B.B("Yaya Dostu Kamp\xfcs","Walkable Campus")
A.aOY=new B.B("Kamp\xfcs de\u011feri, hi\xe7bir \u015fey yap\u0131lmasayd\u0131 olaca\u011f\u0131ndan y\xfcksek olsun","Campus value must end above where doing nothing would leave it")
A.aP0=new B.B("Yemekhane ve bah\xe7e at\u0131\u011f\u0131 kompostu","Composting of canteen and garden waste")
A.aP1=new B.B("I\u015f\u0131k disiplini","Lighting discipline")
A.dv=new B.Gy(2,"collapsed")
A.aP2=new B.B(A.dv,A.dv)
A.aP3=new B.B("3 binan\u0131n \xe7at\u0131s\u0131na g\xfcne\u015f paneli kur.","Install solar panels on 3 rooftops.")
A.aP4=new B.B("Tamamlanan senaryo hedefleri","Scenario goals met")
A.aP5=new B.B("Eylemsiz senaryo (ayn\u0131 d\xf6nem)","No-action scenario (same period)")
A.aP7=new B.B("S\u0131f\u0131r At\u0131k ayr\u0131\u015ft\u0131rma merkezi","Zero Waste sorting centre")
A.KX=new B.B("bin m\xb3/y\u0131l","thousand m\xb3/yr")
A.aP8=new B.B("MWh/y\u0131l","MWh/yr")
A.aP9=new B.B("S\u0131f\u0131r At\u0131k kamp\xfcs\xfc","Zero Waste campus")
A.aPa=new B.B("Ring servisi ve kamp\xfcse ara\xe7la geli\u015fler.","Shuttle service and car trips to campus.")
A.aPb=new B.B("\xdcniversite 2030 net s\u0131f\u0131r taahh\xfcd\xfc verdi. Be\u015f y\u0131lda y\u0131ll\u0131k sal\u0131m\u0131 %20 azalt\u0131rken kamp\xfcs de\u011ferini, hi\xe7bir \u015fey yap\u0131lmasayd\u0131 olaca\u011f\u0131n\u0131n \xfcst\xfcnde tut.","The university has pledged net zero by 2030. Cut annual emissions by 20% in five years while keeping the campus value above where doing nothing would leave it.")
A.aPc=new B.B("Ayd\u0131nl\u0131k Kamp\xfcs","Bright Campus")
A.aPe=new B.B("Ring hatt\u0131ndaki dizel otob\xfcslerin yar\u0131s\u0131 elektrikli otob\xfcslerle de\u011fi\u015fir. Yak\u0131t gideri d\xfc\u015fer; \u015febeke elektri\u011fi kullan\u0131ld\u0131\u011f\u0131 i\xe7in sal\u0131m azal\u0131r ama s\u0131f\u0131rlanmaz.","Half of the diesel shuttle buses are replaced with electric ones. Fuel costs fall; emissions drop but not to zero because grid electricity is used.")
A.aPf=new B.B("\xc7at\u0131 panelleri ve kamp\xfcs GES \xfcretiminin toplam elektrik ihtiyac\u0131na oran\u0131.","Rooftop panel and campus solar plant output over total electricity demand.")
A.aPg=new B.B("Cephe yenileme","Facade renewal")
A.aPi=new B.B("tCO\u2082e","tCO\u2082e")
A.aPj=new B.B("Kullan\u0131lan yat\u0131r\u0131m limiti (bug\xfcne kadar)","Investment limit used (to date)")
A.aPk=new B.B("Is\u0131 yal\u0131t\u0131m\u0131 (mantolama)","Thermal insulation (cladding)")
A.aPl=new B.B("GreenComp tabanl\u0131 oyun i\xe7i g\xf6sterge; \xf6l\xe7me arac\u0131 de\u011fildir.","An in-game indicator based on GreenComp; not an assessment tool.")
A.aPm=new B.B("Ye\u015fil giri\u015fimcilik","Green entrepreneurship")
A.aPn=new B.B("Fak\xfclteler aras\u0131 korunakl\u0131 bisiklet yolu ve istasyonlar. Kamp\xfcse ara\xe7la geli\u015fler %8 azal\u0131r; kamp\xfcse para kazand\u0131rmaz ama sal\u0131m\u0131 ve memnuniyeti iyile\u015ftirir.","Protected bike lanes and stations between faculties. Car trips to campus drop by 8%; it earns no money but improves emissions and satisfaction.")
A.aPq=new B.B("\xd6nerideki ek yetkinlik","Additional competence in the proposal")
A.aPr=new B.B("Musluk ve rezervuarlar tasarruflu modellerle de\u011fi\u015ftirilir; su t\xfcketimi %25 azal\u0131r.","Taps and cisterns are replaced with efficient models; water use drops by 25%.")
A.aPx=new B.B("Binalar\u0131n yar\u0131s\u0131nda LED ayd\u0131nlatmaya ge\xe7.","Switch half of the buildings to LED lighting.")
A.aPy=new B.B("Ekonomik daralma: yat\u0131r\u0131m limiti y\u0131lda 50 milyon \u20ba. En verimli i\u015fleri se\xe7erek sal\u0131m\u0131 azalt, \xf6\u011frencileri memnun tut.","Economic downturn: the investment limit is \u20ba50 million a year. Pick the most efficient jobs to cut emissions and keep students satisfied.")
A.cq=new B.B("Ba\u015flang\u0131\xe7","Start")
A.aPB=new B.B("\u015eebekeden net elektrik","Net grid electricity")
A.aPC=new B.B("B\xf6lgenin asfalt\u0131n\u0131 yenile","Resurface the zone")
A.aPD=new B.B("Uygulama i\xe7i kural: sim\xfclasyon sonuna kadar kendini \xf6deyen ya da y\u0131lda en az 1 tCO\u2082e azaltan i\u015flerin harcamadaki pay\u0131.","In-app rule: share of spending on jobs that pay back by the end of the simulation or cut at least 1 tCO\u2082e a year.")
A.aPE=new B.B("Karbon -%25","Carbon -25%")
A.aPF=new B.B("Su tasarrufu ya da ya\u011fmur hasad\u0131 olan binalar","Buildings with water saving or rainwater harvesting")
A.aPG=new B.B("Kamp\xfcs S\u0131f\u0131r At\u0131k belgesine ba\u015fvuracak. At\u0131k ayr\u0131\u015ft\u0131rma ve kompostu kur, su t\xfcketimini d\xfc\u015f\xfcr, memnuniyeti koru.","The campus will apply for the Zero Waste certificate. Set up waste sorting and composting, cut water use and keep satisfaction.")
A.aPH=new B.B("\xc7atlak ve \xe7ukurlar onar\u0131l\u0131r; bu noktan\u0131n asfalt\u0131 yenilenir.","Cracks and potholes are repaired; the asphalt at this point is renewed.")
A.aPI=new B.B("Elektrikte yerinde g\xfcne\u015f pay\u0131","On-site solar share of electricity")
A.aPJ=new B.B("Su tasarruflu armat\xfcr","Water-saving fixtures")
A.aPK=new B.B("Ayr\u0131\u015ft\u0131rma merkezi ve kompost \xe7al\u0131\u015fs\u0131n","Sorting centre and composting in operation")
A.KY=new B.B("Rakamlar sim\xfclasyon modelinden hesaplan\u0131r: t\xfcketimler bina tipine g\xf6re temsili de\u011ferlerdir, saya\xe7 \xf6l\xe7\xfcm\xfc de\u011fildir; emisyon fakt\xf6rleri yakla\u015f\u0131kt\u0131r.","Figures are computed by the simulation model: consumption uses representative values by building type, not metered data; emission factors are approximate.")
A.aPN=new B.B("Toplumsal sorumluluk","Social responsibility")
A.aPO=new B.B("Is\u0131tman\u0131n b\xfcy\xfck k\u0131sm\u0131 do\u011falgaz yerine elektrikle yap\u0131l\u0131r: gaz %55 azal\u0131r, elektrik artar. Faturadan \xe7ok karbonda kazand\u0131r\u0131r.","Most heating switches from gas to electricity: gas drops 55%, electricity rises. It saves more carbon than money.")
A.fG=new B.B("","")
A.aPQ=new B.B("Koridor, s\u0131n\u0131f ve tuvaletlere hareket sens\xf6r\xfc ve zaman ayar\u0131: bo\u015f odada \u0131\u015f\u0131k yanmaz. Elektrik %6 azal\u0131r; LED ile birlikte de i\u015fe yarar.","Occupancy sensors and timers in corridors, classrooms and toilets: no lights in empty rooms. Electricity drops by 6%; it also works on top of LED.")
A.aPR=new B.B("Hedefler uygulama i\xe7i varsay\u0131md\u0131r, resm\xee hedef de\u011fildir.","Goals are in-app assumptions, not official targets.")
A.aPS=new B.B("Bug\xfcne kadarki toplam sal\u0131m","Total emissions to date")
A.aPT=new B.B("Bo\u015f araziye g\xfcne\u015f santrali kurulur; y\u0131lda ~3.000 MWh elektrik \xfcretir, faturay\u0131 ve sal\u0131m\u0131 d\xfc\u015f\xfcr\xfcr.","A solar plant on vacant land produces ~3,000 MWh a year, cutting bills and emissions.")
A.aPU=new B.B("Temiz Enerji","Clean Energy")
A.aPV=new B.B("\u0130lk y\u0131ldan sonra memnuniyeti 85 \xfcst\xfcnde tut.","Keep satisfaction above 85 after the first year.")
A.aPW=new B.B("Elektrikli ring servisini ve bisiklet yollar\u0131n\u0131 hayata ge\xe7ir.","Launch the electric shuttle and the bike lanes.")
A.aPX=new B.B("Sistem d\xfc\u015f\xfcncesi","Systems thinking")
A.aPZ=new B.B("Kendini \xf6deyen ya da sal\u0131m\u0131 azaltan yat\u0131r\u0131m pay\u0131","Investment that pays back or cuts emissions")
A.aQ_=new B.B("Ye\u015fil Ula\u015f\u0131m","Green Mobility")
A.aQ0=new B.B("Ya\u011fmur suyu drenaj\u0131","Stormwater drainage")
A.aQ1=new B.B("Gelecek odakl\u0131 d\xfc\u015f\xfcnme","Futures thinking")
A.aQ2=new B.B("Net s\u0131f\u0131r yolu","Path to net zero")
A.aQ3=new B.B("\xc7at\u0131 suyu depoda toplan\u0131r, sulama ve rezervuarlarda kullan\u0131l\u0131r; \u015febeke suyu %15 azal\u0131r.","Roof water is stored and used for irrigation and cisterns; mains water drops by 15%.")
A.aQ4=new B.B("Bisiklet yollar\u0131 ve payla\u015f\u0131ml\u0131 bisiklet","Bike lanes and bike sharing")
A.aQ5=new B.B("LED ayd\u0131nlatma","LED lighting")
A.KZ=new B.B("/ 100","/ 100")
A.aQ6=new B.B("GreenComp \xb7 S\xfcrd\xfcr\xfclebilirlik i\xe7in karma\u015f\u0131kl\u0131\u011f\u0131 kucaklamak","GreenComp \xb7 Embracing complexity in sustainability")
A.aQ7=new B.B("Karbon -%10","Carbon -10%")
A.aQ8=new B.B("Kamp\xfcs g\xfcne\u015f santrali (2 MWp)","Campus solar plant (2 MWp)")
A.aQ9=new B.B("Do\u011falgazs\u0131z Bina","Gas-Free Building")
A.aQa=new B.B("\xc7at\u0131ya g\xfcne\u015f paneli","Rooftop solar panels")
A.aQb=new B.B("Y\u0131ll\u0131k sera gaz\u0131 sal\u0131m\u0131","Annual greenhouse gas emissions")
A.aQc=new B.B("Y\u0131ll\u0131k sal\u0131m\u0131 ba\u015flang\u0131ca g\xf6re %10 azalt.","Cut annual emissions by 10% from the start.")
A.aQd=new B.B("Y\u0131ll\u0131k sal\u0131m\u0131 ba\u015flang\u0131ca g\xf6re %25 azalt.","Cut annual emissions by 25% from the start.")
A.aQe=new B.B("\xc7at\u0131 alan\u0131na g\xf6re g\xfcne\u015f paneli kurulur ve binan\u0131n elektri\u011finin bir k\u0131sm\u0131n\u0131 \xfcretir.","Solar panels sized to the roof produce part of the building's electricity.")
A.aQf=new B.B("Ye\u015fil yetkinlik profili ortalamas\u0131","Average green competence score")
A.aQg=new B.B("Eylemsiz senaryoyla kar\u015f\u0131la\u015ft\u0131rmak i\xe7in sim\xfclasyonu duraklat.","Pause the simulation to compare.")
A.aQh=new B.B("B\xf6lgedeki t\xfcm yollar yeniden asfaltlan\u0131r; yeni asfalt \xe7ok daha yava\u015f y\u0131pran\u0131r.","All roads in the zone are resurfaced; new asphalt wears much more slowly.")
A.aQi=new B.B("Su t\xfcketimi","Water use")
